import os
import shutil

from delta.tables import DeltaTable


def build_table(trips, path):
    # The day's two writes, replayed on a fresh table. Don't change this.
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    # repartition(n) splits the trips into n parts, so a write makes up to n files.
    trips.repartition(3).write.format("delta").save(path)  # the morning load
    trips.repartition(2).write.format("delta").mode("overwrite").save(path)  # the nightly rewrite


def files_on_disk(path):
    # Every Parquet file in the table's folder (the log is a sub-folder, so it isn't counted).
    return len([f for f in os.listdir(path) if f.endswith(".parquet")])


def report(version, files_in_table, files_in_folder):
    return spark.createDataFrame(
        [(version, files_in_table, files_in_folder)],
        "version BIGINT, files_in_table INT, files_in_folder INT",
    )


def solve(trips):
    path = "/tmp/taxi/trips"
    build_table(trips, path)
    # Fill in the three numbers.
    return report(0, 0, 0)
